walk.content:
const s = JSON.parse(state);
const E = s.packages.engine;
const time = E.utilities.time.properties.state;
const kb = E.packages.controllers.utilities['keyboard-0'];
const pt = E.packages.controllers.utilities['pointer-0'];
const left = E.packages.controllers.utilities['xr-controller-left'];
const right = E.packages.controllers.utilities['xr-controller-right'];
const me = s.packages.player;
const d = me.properties.meta.data;
const dt = Math.min(time.delta, 0.1);

const view = me.packages.head.utilities.camera.properties.state;
const vr = !!(view && view.presenting);

let yaw = d.yaw || 0;
let pitch = d.pitch || 0;
const turned = yaw;

let mx = 0;
let mz = 0;
let rate = 4.6;

if (vr) {

	// The headset supplies pitch and the whole of the look direction; the
	// document only owns the heading the rig is turned to.
	pitch = 0;

	const rs = right ? right.properties.state.analog : null;
	yaw -= ((rs && rs['thumbstick-x']) || 0) * 2.2 * dt;

	// Walk where the left controller points, flattened onto the ground. The
	// ray is reported in world space, and the reference space the controller
	// is tracked in already carries the heading the player has turned to, so
	// "relative to the way you are facing" needs no further work here.
	const ls = left ? left.properties.state.analog : null;
	const lx = (ls && ls['thumbstick-x']) || 0;
	const ly = (ls && ls['thumbstick-y']) || 0;

	let fx = -Math.sin(yaw);
	let fz = -Math.cos(yaw);

	const ray = left && left.properties.state.ray
		? left.properties.state.ray.direction : null;

	if (ray) {
		const flat = Math.hypot(ray[0], ray[2]);
		if (flat > 1e-3) { fx = ray[0] / flat; fz = ray[2] / flat; }
	}

	// Right of that heading, in a right handed Y up frame.
	mx = fx * ly - fz * lx;
	mz = fz * ly + fx * lx;

	const grip = left ? left.properties.state.digital : [];
	rate = grip.indexOf('squeeze') >= 0 ? 11 : 4.6;

} else {

	if (pt) {
		const a = pt.properties.state.analog;
		yaw -= (a.dx || 0) * 3.2;
		pitch += (a.dy || 0) * 3.2;
		pitch = Math.max(-1.35, Math.min(1.35, pitch));
	}

	const keys = kb ? kb.properties.state.digital : [];
	const on = k => keys.indexOf(k) >= 0;

	const forward = (on('KeyW') || on('ArrowUp') ? 1 : 0) - (on('KeyS') || on('ArrowDown') ? 1 : 0);
	const strafe = (on('KeyD') || on('ArrowRight') ? 1 : 0) - (on('KeyA') || on('ArrowLeft') ? 1 : 0);

	const sy = Math.sin(yaw), cy = Math.cos(yaw);
	mx = -sy * forward + cy * strafe;
	mz = -cy * forward - sy * strafe;

	rate = (on('ShiftLeft') || on('ShiftRight') ? 12 : 4.6);
}

// A stick half pushed walks half as fast; two keys held is still one speed.
const heading = Math.hypot(mx, mz);
const drive = Math.min(1, heading);

if (heading > 1e-6) { mx /= heading; mz /= heading; }

const probe = me.utilities.ground.properties.state;
const hits = probe ? probe.hits : null;
const surface = hits && hits.length ? hits[0] : null;

// Slope normalisation. Crossing a horizontal distance h over ground of
// gradient g covers h * sqrt(1 + g*g) of actual surface, so holding the
// distance travelled along the surface constant means shortening the
// horizontal step by that same factor.
let grade = 0;

if (surface && surface.normal && Math.abs(surface.normal[1]) > 1e-3) {
	const n = surface.normal;
	grade = -(mx * n[0] + mz * n[2]) / n[1];
}

// The overlap that stops a body is a frame behind it, so a step larger than
// the body cannot be caught before it has passed through something thin.
// Capping the step against the radius bounds that, and only ever bites at a
// frame rate far below playable.
const step = Math.min(
	rate * drive * dt / Math.sqrt(1 + grade * grade),
	(d.radius || 0.5) * 0.7
);

let px = d.position[0] + mx * step;
let pz = d.position[2] + mz * step;

// Turn about where the head actually is rather than about the rig origin.
// Otherwise a player who has stepped away from the centre of their space is
// swung sideways every time they rotate.
if (false && vr && view.offset && Math.abs(yaw - turned) > 1e-9) {

	const h = view.offset;

	// A head is never more than arm's reach from the middle of a play space.
	// Anything larger is not a head offset at all but a position reported in
	// some other frame, and turning about it would hurl the player across the
	// map. Turn about the rig instead, which is merely less comfortable.
	if (Math.hypot(h[0], h[2]) < 3) {

		const spin = (x, z, a) => [
			x * Math.cos(a) + z * Math.sin(a),
			-x * Math.sin(a) + z * Math.cos(a)
		];

		const was = spin(h[0], h[2], turned);
		const now = spin(h[0], h[2], yaw);

		// And even a valid offset cannot justify moving further in one frame
		// than a person can lean.
		px += Math.max(-0.5, Math.min(0.5, was[0] - now[0]));
		pz += Math.max(-0.5, Math.min(0.5, was[1] - now[1]));
	}
}

// Push out of anything solid already overlapped. Only the horizontal part
// of each normal is used, so being blocked can never raise the player.
const bump = me.utilities.bump.properties.state;
const radius = d.radius || 0.5;

if (bump && bump.hits) {
	for (const hit of bump.hits) {
		const depth = radius - hit.distance;
		if (depth <= 0) continue;
		const n = hit.normal;
		const flat = Math.hypot(n[0], n[2]);
		if (flat < 1e-4) continue;
		px += (n[0] / flat) * depth;
		pz += (n[2] / flat) * depth;
	}
}

const edge = 150;
px = Math.max(-edge, Math.min(edge, px));
pz = Math.max(-edge, Math.min(edge, pz));

let py = d.position[1];
let lost = d.lost || 0;

if (surface) {

	lost = 0;

	// Ease onto ground that is near, but close a large gap outright, so one
	// bad frame cannot leave the player drifting above or below the map.
	const g = surface.point[1];
	py = Math.abs(g - py) > 4 ? g : py + (g - py) * Math.min(1, 14 * dt);

} else {

	// The probe is cast from above the player, so a player who has ended up
	// further below the map than the probe reaches can never find the ground
	// again. Rather than fall forever, climb back to an altitude the probe
	// can certainly see from and let it re-acquire.
	lost += 1;

	if (lost > 3) { py = 80; lost = 0; }
}

// Nothing in this scene belongs outside this band. Reaching it means
// something has gone wrong, and staying there means never recovering.
if (py > 400 || py < -400) { py = 80; lost = 0; }

const moving = drive > 0.01 ? 1 : 0;
const moved = Math.hypot(px - d.position[0], py - d.position[1], pz - d.position[2]);
const eye = d.eye || 1.75;

return JSON.stringify({ packages: { player: {
	properties: { meta: { data: {
		position: [px, py, pz],
		rotation: [0, yaw, 0],
		yaw: yaw,
		pitch: pitch,
		moving: moving,
		grade: grade,
		lost: lost,
		vr: vr ? 1 : 0,
		speed: dt > 0 ? moved / dt : 0,
		distance: (d.distance || 0) + (moving ? moved : 0)
	} } },
	packages: { head: { properties: { meta: { data: {
		// A floor relative session measures eye height itself.
		position: vr ? [0, 0, 0] : [0, eye, 0],
		rotation: [pitch, 0, 0]
	} } } } }
} } });

start.content:
const s = JSON.parse(state);
const display = s.packages.engine.utilities.display.properties.state;
const track = s.packages.ambience.utilities.track.properties;

if (!display.gesture) return;
if (!track.state || !track.state.loaded) return;
if (track.state.playing) return;
if (s.packages.ambience.properties.meta.data.started) return;

return JSON.stringify({ packages: { ambience: {
	properties: { meta: { data: { started: true } } },
	utilities: { track: { properties: { data: { play: true } } } }
} } });

lock.content:
const s = JSON.parse(state);
if (s.packages.engine.utilities.display.properties.data.cursor === 'locked') return;
return JSON.stringify({ packages: { engine: { utilities: { display: { properties: { data: { cursor: 'locked' } } } } } } });

settle.content:
const s = JSON.parse(state);
const marks = s.packages.landmarks.packages;
const patch = {};
let dirty = false;

Object.keys(marks).forEach(name => {
	const mark = marks[name];
	const data = mark.properties.meta.data;
	if (data.settled) return;
	const probe = mark.utilities.probe;
	if (!probe || !probe.properties.state) return;
	const hits = probe.properties.state.hits;
	if (!hits || !hits.length) return;
	const p = data.position;
	patch[name] = { properties: { meta: { data: {
		position: [p[0], hits[0].point[1] + (data.rise || 0), p[2]],
		settled: true
	} } }, utilities: { probe: null } };
	dirty = true;
});

if (!dirty) return;
return JSON.stringify({ packages: { landmarks: { packages: patch } } });

status.content:
const s = JSON.parse(state);
const E = s.packages.engine;
const time = E.utilities.time.properties.state;
const display = E.utilities.display.properties.state;
const hud = s.packages.hud;
const patch = { packages: { hud: { packages: {} , utilities: {} } } };
let dirty = false;

// The prompt is shown only while the pointer is free.
const wantPrompt = !display.locked && !display.xr.presenting;
if (hud.packages.prompt.properties.meta.data.enabled !== wantPrompt) {
	patch.packages.hud.packages.prompt = { properties: { meta: { data: { enabled: wantPrompt } } } };
	dirty = true;
}

// The readout is rebuilt on change, so it is refreshed a few times a second.
if (time.frame % 20 === 0) {
	const p = s.packages.player.properties.meta.data;
	const probe = s.packages.player.utilities.ground.properties.state;
	const ground = probe && probe.hits.length ? probe.hits[0].point[1].toFixed(0) : '--';
	const heading = Math.round(((-p.yaw * 180 / Math.PI) % 360 + 360) % 360);
	const v = s.packages.player.packages.head.utilities.camera.properties.state;
	if (p.vr) {
		const o = v && v.offset ? v.offset : [0, 0, 0];
		const line = (p.speed || 0).toFixed(1) + 'm/s   ' +
			Math.round(p.distance || 0) + 'm   grade ' + (p.grade || 0).toFixed(2) +
			'   pos ' + p.position.map(n => n.toFixed(0)).join(' ') +
			'   ' + (v && v.rigged ? v.rigged : 'no rig');
		if (hud.utilities.readout.content !== line) {
			patch.packages.hud.utilities.readout = { content: line };
			dirty = true;
		}
		if (dirty) return JSON.stringify(patch);
		return;
	}
	const line = Math.round(p.distance || 0) + 'm   ' + heading + '\u00b0   ' + (p.speed || 0).toFixed(1) + 'm/s   grade ' + (p.grade || 0).toFixed(2) + '   ' + display.fps + 'fps' + (display.xr.presenting ? '   VR' : '');
	if (hud.utilities.readout.content !== line) {
		patch.packages.hud.utilities.readout = { content: line };
		dirty = true;
	}
}

if (!dirty) return;
return JSON.stringify(patch);
